// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { IVToken } from "./IVToken.sol";

interface IFlashLoanReceiver {
    /**
     * @notice Executes an operation after receiving the flash-borrowed assets.
     * @dev Implementation of this function must ensure at least the premium (fee) is repaid within the same transaction.
     *      Any unpaid balance (principal + premium - repaid amount) will be added to the onBehalf address's borrow balance.
     * @param vTokens The vToken contracts corresponding to the flash-borrowed underlying assets.
     * @param amounts The amounts of each underlying asset that were flash-borrowed.
     * @param premiums The premiums (fees) associated with each flash-borrowed asset.
     * @param initiator The address that initiated the flash loan.
     * @param onBehalf The address of the user whose debt position will be used for any unpaid flash loan balance.
     * @param param Additional parameters encoded as bytes. These can be used to pass custom data to the receiver contract.
     * @return success True if the operation succeeds (regardless of repayment amount), false if the operation fails.
     * @return repayAmounts Array of uint256 representing the amounts to be repaid for each asset. The receiver contract
     *         must approve these amounts to the respective vToken contracts before this function returns.
     */
    function executeOperation(
        IVToken[] calldata vTokens,
        uint256[] calldata amounts,
        uint256[] calldata premiums,
        address initiator,
        address onBehalf,
        bytes calldata param
    ) external returns (bool success, uint256[] memory repayAmounts);
}

contracts/Interfaces/IILComptroller.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

/**
 * @title IILComptroller
 * @notice Interface for Isolated Lending (IL) comptrollers.
 * @dev IL comptrollers differ from the Diamond proxy: markets() returns a 3-value tuple
 *      and setCollateralFactor returns void instead of uint256.
 */
interface IILComptroller {
    /// @notice Market metadata returned by the IL comptroller.
    /// @param isListed Whether the market is listed.
    /// @param collateralFactorMantissa The collateral factor (scaled by 1e18).
    /// @param liquidationThresholdMantissa The liquidation threshold (scaled by 1e18).
    struct Market {
        bool isListed;
        uint256 collateralFactorMantissa;
        uint256 liquidationThresholdMantissa;
    }

    /// @notice Set the collateral factor and liquidation threshold for a market.
    /// @param vToken The vToken market address.
    /// @param newCollateralFactorMantissa The new collateral factor (scaled by 1e18).
    /// @param newLiquidationThresholdMantissa The new liquidation threshold (scaled by 1e18).
    function setCollateralFactor(
        address vToken,
        uint256 newCollateralFactorMantissa,
        uint256 newLiquidationThresholdMantissa
    ) external;

    /// @notice Get the market metadata for a vToken.
    /// @param vToken The vToken market address.
    /// @return market The market metadata.
    function markets(address vToken) external view returns (Market memory market);

    /// @notice Enter a market for an account. The caller needs the ACM permission for `enterMarketForAccount(address,address)`.
    /// @param account The account to enter the market for.
    /// @param vToken The vToken market address.
    function enterMarketForAccount(address account, address vToken) external;
}

